<nav class="print-controls" aria-label="Thao tác in"><button type="button" id="print-document"><?=$kind==='order'?'In phiếu':'In biên bản'?></button><a href="/admin#<?=$kind==='order'?'orders':'shifts'?>">Quay lại quản trị</a>
