<?php if($kind==='order'):$s=$d['snapshot'];$groups=['ADULT'=>'Người lớn','CHILD'=>'Trẻ em','SENIOR'=>'Người cao tuổi','LOCAL_ADULT'=>'Người lớn địa phương','LOCAL_CHILD'=>'Trẻ em địa phương','LOCAL_SENIOR'=>'Người cao tuổi địa phương'];?>
