<p>Ngày tạo: <?=$e($time($d['createdAt']))?> (GMT+7)</p><p>Khách: <strong><?=$e($d['contact']['name'])?></strong> · <?=$e($d['contact']['phone'])?></p><p>Email: <?=$e($d['contact']['email'])?></p>
