<?php foreach(['onlineDiscount'=>'Ưu đãi online','discount'=>'Mã giảm giá'] as $key=>$label):if(isset($s[$key])):?><p><?=$e($label)?><?=$e(isset($s[$key]['code'])?' '.$s[$key]['code']:'')?>: −<?=$e($money($s[$key]['amount']))?></p><?php endif;endforeach;?>
