<?php else:$s=$d['summary'];?>
<p>Mã ca: <?=$e($d['id'])?> · v<?=$e($d['version'])?></p><p>Người mở: <?=$e($d['openedName'])?></p><p>Mở ca: <?=$e($time($d['openedAt']))?> · Chốt ca: <?=$e($time($d['closedAt']))?> (GMT+7)</p><p>Người chốt (mã tài khoản): <?=$e($d['closedBy'])?></p><p>Số khoản thu: <?=$e($s['receiptCount'])?></p>
<table><tbody><?php foreach(['openingCash'=>'Tiền mặt đầu ca','cash'=>'Tiền mặt đã thu','bank'=>'Chuyển khoản đã thu','cashIn'=>'Bổ sung tiền mặt','cashOut'=>'Rút/chi tiền mặt','expectedCash'=>'Tiền mặt theo sổ phải bàn giao','countedCash'=>'Tiền mặt thực đếm','difference'=>'Chênh lệch (thừa + / thiếu −)'] as $key=>$label):?><tr><th><?=$e($label)?></th><td class="money"><?=$e($money($key==='openingCash'?$d['openingCash']:$s[$key]))?></td></tr><?php endforeach;?></tbody></table>
