<?php if($d['movements']):?><h2>Thu/chi tiền mặt ngoài bán vé</h2><table><thead><tr><th>Thời gian / chứng từ</th><th>Loại / lý do / người ghi</th><th>Số tiền</th></tr></thead><tbody><?php foreach($d['movements'] as $m):?><tr><td><?=$e($time($m['created_at']))?><p><?=$e($m['reference'])?></p></td><td><?=$m['kind']==='IN'?'Bổ sung':'Rút/chi'?><p class="preserve"><?=$e($m['note'])?></p><?=$e($m['actor_name'])?></td><td class="money"><?=$e($money($m['amount']))?></td></tr><?php endforeach;?></tbody></table><?php endif;?>
<div class="signatures"><?php foreach(['Người giao','Người nhận','Người kiểm tra'] as $label):?><div><strong><?=$e($label)?></strong><small>(Ký, ghi rõ họ tên)</small></div><?php endforeach;?></div><p><small>Biên bản nội bộ · Đơn vị tiền VND · Hoàn thiện chữ ký khi bàn giao.</small></p>
<?php endif;?></article>
<?php if($kind==='shift'):?><article class="sheet annex" id="receipt-annex" hidden><h2>Chi tiết khoản thu trong ca</h2><p><?=$e($d['counterName'])?> · <?=$e($d['id'])?></p><table><thead><tr><th>Đơn / thời gian thu (GMT+7)</th><th>Phương thức / mã giao dịch</th><th>Số tiền</th></tr></thead><tbody><?php foreach($d['receipts'] as $r):?><tr><td><?=$e($r['code'])?><p><?=$e($time($r['created_at']))?></p></td><td><?=$r['method']==='CASH'?'Tiền mặt':'Chuyển khoản'?><p><?=$e($r['reference'])?></p></td><td class="money"><?=$e($money($r['amount']))?></td></tr><?php endforeach;?></tbody></table></article><?php endif;?></main></body></html>
